/*
 * Side-channel challenge: M/o/Vfuscator timing oracle.
 *
 * The binary is compiled with the M/o/Vfuscator, so the disassembly is
 * essentially a sea of `mov` instructions.  The actual logic is hidden
 * behind a huge lookup-table dispatch, which makes static analysis
 * of the secret painful.
 *
 * The flag is NOT stored as a contiguous string literal.  Each byte
 * is reconstructed at runtime from two non-string arrays (so `strings`
 * and friends do not give the flag away for free).  The arrays are
 * generated by tools/gen_flag.py.
 *
 * The intentional side channel is a TIMING oracle:
 *   - argv[1] is a candidate string.
 *   - For every position i, the program performs `argv[1][i] * SCALE`
 *     units of dummy work, then compares argv[1][i] to FLAG[i].
 *   - On mismatch it exits early.
 *   - On full match it prints "correct".
 *
 * Compile:   movcc chall.c -o chall
 */

#include <stdio.h>
#include <string.h>

/* Auto-generated by tools/gen_flag.py -- do not edit by hand. */
/* flag = 'nmctf{m0v_th3_fl4g_l0rd}'  */
/* key  = 6b1f3c0d8a72e5b4f9c6a3e8b1d4f7c2a5e8b1d4f7c2a5e8  */
static const unsigned char BASE[] = {
    0x6b, 0x1f, 0x3c, 0x0d, 0x8a, 0x72, 0xe5, 0xb4,
    0xf9, 0xc6, 0xa3, 0xe8, 0xb1, 0xd4, 0xf7, 0xc2,
    0xa5, 0xe8, 0xb1, 0xd4, 0xf7, 0xc2, 0xa5, 0xe8,
};
static const unsigned char ADD[]  = {
    0x03, 0x4e, 0x27, 0x67, 0xdc, 0x09, 0x88, 0x7c,
    0x7d, 0x99, 0xd1, 0x80, 0x82, 0x8b, 0x6f, 0xaa,
    0x8f, 0x7f, 0xae, 0x98, 0x39, 0xb0, 0xbf, 0x95,
};
#define FLAG_LEN 24

/* Work scale per char.  Tuned for a quick-but-reliable oracle. */
#define SCALE 300

int main(int argc, char **argv)
{
    int i, j;
    char c;
    int dummy;
    int res;
    char flag[FLAG_LEN];
    char target;

    if (argc != 2) {
        printf("usage: %s <candidate>\n", argv[0]);
        return 1;
    }

    /* Reconstruct the flag at runtime. */
    for (i = 0; i < FLAG_LEN; i++) {
        flag[i] = (char)((BASE[i] + ADD[i]) & 0xff);
    }

    /* Sink for the dummy work so the optimiser cannot remove it. */
    dummy = 0;

    for (i = 0; i < FLAG_LEN; i++) {
        target = flag[i];
        c = argv[1][i];

        /* Per-character work proportional to the INPUT value.
         * Together with the early-exit on mismatch, this gives a
         * per-position yes/no oracle that can be amplified by trying
         * a fixed tail past position k.                              */
        for (j = 0; j < (int)((unsigned char)c) * SCALE; j++) {
            dummy = (dummy * 31 + j) ^ (dummy >> 7);
        }

        if (c != target) {
            /* Early exit on mismatch — this is the oracle. */
            return 0;
        }
    }

    /* All characters matched.  Also assert the input is the same length. */
    res = (argv[1][FLAG_LEN] != '\0');
    if (res) {
        return 0;
    }

    printf("correct\n");
    return 0;
}
